    {"id":"cranberry_extract","name":"Cranberry Extract (UTI Prevention)","name_ja":"クランベリー抽出物（UTI予防）","category":"miscellaneous","mechanism":"Proanthocyanidins inhibit bacterial (E. coli) adhesion to uroepithelium","mechanism_ja":"プロアントシアニジンが細菌（大腸菌）の尿路上皮への接着を阻害","species_info":{"dog":{"dose":"100-400 mg/dog PO q12-24h（製品に依存）","notes_ja":"再発性UTIの予防補助。治療には不十分","notes":"Recurrent UTI prevention adjunct. Insufficient for treatment"},"cat":{"dose":"犬用製品の猫用量は確立されていない。獣医用サプリメント使用","notes_ja":"再発性UTI予防の補助","notes":"Recurrent UTI prevention adjunct"}},"side_effects":"GI upset (rare), potential calcium oxalate stone risk","side_effects_ja":"消化器症状（稀）、シュウ酸カルシウム結石リスクの可能性","contraindications":"Calcium oxalate urolithiasis history","contraindications_ja":"シュウ酸カルシウム尿石症既往","drug_interactions":[]},
    {"id":"pepcid_antacid","name":"Famotidine Oral (Pepcid)","name_ja":"ファモチジン経口（ガスター）","category":"gastrointestinal","mechanism":"H2 receptor antagonist; reduces gastric acid secretion","mechanism_ja":"H2受容体拮抗薬。胃酸分泌抑制","species_info":{"dog":{"dose":"0.5-1 mg/kg PO q12-24h","notes_ja":"胃炎・消化管潰瘍予防。PPIより弱いが安全性高い","notes":"Gastritis, GI ulcer prevention. Weaker than PPIs but safer profile"},"cat":{"dose":"0.5-1 mg/kg PO q12-24h","notes_ja":"猫の尿毒症性胃炎・嘔吐","notes":"Feline uremic gastritis, vomiting"},"rabbit":{"dose":"0.5-1 mg/kg PO q12h","notes_ja":"消化管潰瘍予防","notes":"GI ulcer prevention"},"ferret":{"dose":"0.5-1 mg/kg PO q12h","notes_ja":"ヘリコバクター性胃炎","notes":"Helicobacter gastritis"},"bird":{"dose":"0.5-2 mg/kg PO q12h","notes_ja":"消化管保護","notes":"GI protection"}},"side_effects":"Rare; headache, constipation","side_effects_ja":"稀。頭痛、便秘","contraindications":"None significant","contraindications_ja":"特になし","drug_interactions":[]},
    {"id":"omeprazole_oral","name":"Omeprazole Oral (Prilosec)","name_ja":"オメプラゾール経口（オメプラール）","category":"gastrointestinal","mechanism":"Proton pump inhibitor; irreversibly blocks H+/K+-ATPase. Most potent acid suppression","mechanism_ja":"プロトンポンプ阻害薬。H+/K+-ATPaseを不可逆的に阻害。最強の酸分泌抑制","species_info":{"dog":{"dose":"1-2 mg/kg PO q12-24h","notes_ja":"消化管潰瘍・GERD・酸分泌亢進。H2RAより強力。3-5日で最大効果","notes":"GI ulcers, GERD, acid hypersecretion. More potent than H2RAs. Max effect in 3-5 days"},"cat":{"dose":"1 mg/kg PO q24h","notes_ja":"消化管潰瘍・嘔吐の補助","notes":"GI ulcers, vomiting adjunct"},"horse":{"dose":"4 mg/kg PO q24h（胃潰瘍治療）; 1-2 mg/kg（予防）","notes_ja":"馬の胃潰瘍第一選択。GastroGard（経口ペースト）。28日間治療","notes":"First-line equine gastric ulcers. GastroGard paste. 28-day treatment"}},"side_effects":"GI upset, hepatic enzyme changes, theoretical B12 deficiency (long-term)","side_effects_ja":"消化器症状、肝酵素変化、B12欠乏（長期使用の理論的リスク）","contraindications":"None significant","contraindications_ja":"特になし","drug_interactions":[{"drug":"ketoconazole","severity":"moderate","description_ja":"ケトコナゾール吸収低下（胃酸減少）","description":"Decreased ketoconazole absorption (reduced gastric acid)"},{"drug":"clopidogrel","severity":"moderate","description_ja":"クロピドグレル活性化阻害の可能性","description":"May inhibit clopidogrel activation"}]},
    {"id":"dexmedetomidine_oromucosal","name":"Dexmedetomidine Oromucosal Gel (Sileo)","name_ja":"デクスメデトミジン口腔粘膜ゲル（サイレオ）","category":"behavioral","mechanism":"α2-adrenergic agonist; anxiolytic and sedative via oromucosal absorption","mechanism_ja":"α2アドレナリン作動薬。口腔粘膜吸収による抗不安・鎮静","species_info":{"dog":{"dose":"125 μg/m² 口腔粘膜（頬と歯茎の間）; 2時間後に再投与可","notes_ja":"犬の騒音恐怖症（花火・雷）に認可。在宅での非注射型鎮静","notes":"Approved for canine noise aversion (fireworks/thunder). Non-injectable home sedation"}},"side_effects":"Sedation, pallor of mucous membranes, bradycardia, low blood pressure","side_effects_ja":"鎮静、粘膜蒼白、徐脈、低血圧","contraindications":"Cardiovascular disease, hepatic/renal impairment, <16 weeks age","contraindications_ja":"心血管疾患、肝/腎機能障害、16週齢未満","drug_interactions":[{"drug":"other_sedatives","severity":"moderate","description_ja":"鎮静の相加","description":"Additive sedation"}]},
    {"id":"thyroxine_monitoring","name":"Free T4 by Equilibrium Dialysis (Diagnostic)","name_ja":"遊離T4（平衡透析法、診断）","category":"endocrine","mechanism":"Diagnostic test; measures unbound active thyroid hormone. Gold standard for thyroid assessment","mechanism_ja":"診断検査。非結合活性型甲状腺ホルモンを測定。甲状腺評価のゴールドスタンダード","species_info":{"dog":{"dose":"検査のみ（参考範囲: 7-28 pmol/L）","notes_ja":"犬の甲状腺機能低下症確定診断。NTI（非甲状腺疾患）との鑑別","notes":"Canine hypothyroidism confirmation. Differentiates from NTI (non-thyroidal illness)"},"cat":{"dose":"検査のみ（参考範囲: 12-33 pmol/L）","notes_ja":"猫の甲状腺機能亢進症。総T4正常だが臨床的に疑わしい場合の追加検査","notes":"Feline hyperthyroidism. Additional test when total T4 normal but clinically suspicious"}},"side_effects":"Not applicable (diagnostic)","side_effects_ja":"該当なし（診断検査）","contraindications":"None","contraindications_ja":"なし","drug_interactions":[]},
    {"id":"zonisamide_oral","name":"Zonisamide","name_ja":"ゾニサミド","category":"behavioral","mechanism":"Blocks sodium and T-type calcium channels; enhances GABA activity. Novel anticonvulsant","mechanism_ja":"NaチャネルとT型Caチャネルを遮断。GABA活性を増強。新規抗てんかん薬","species_info":{"dog":{"dose":"5-10 mg/kg PO q12h","notes_ja":"フェノバルビタール/KBrの追加療法。肝毒性なし（PB代替として有用）","notes":"Add-on to phenobarbital/KBr. No hepatotoxicity (useful PB alternative)"},"cat":{"dose":"5-10 mg/kg PO q12-24h","notes_ja":"猫のてんかん。レベチラセタムの代替","notes":"Feline epilepsy. Levetiracetam alternative"}},"side_effects":"Sedation, ataxia, inappetence, hepatotoxicity (rare), idiosyncratic reactions","side_effects_ja":"鎮静、運動失調、食欲不振、肝毒性（稀）、特異体質反応","contraindications":"Sulfonamide allergy, severe hepatic/renal disease","contraindications_ja":"サルファ剤アレルギー、重度肝/腎疾患","drug_interactions":[{"drug":"phenobarbital","severity":"moderate","description_ja":"ゾニサミド代謝促進→用量増加必要","description":"Increased zonisamide metabolism, dose increase needed"}]},
    {"id":"potassium_bromide","name":"Potassium Bromide (KBr)","name_ja":"臭化カリウム（KBr）","category":"behavioral","mechanism":"Bromide ion competes with chloride at GABA-A receptor, enhancing inhibitory neurotransmission","mechanism_ja":"臭化物イオンがGABA-A受容体で塩化物と競合し、抑制性神経伝達を増強","species_info":{"dog":{"dose":"20-40 mg/kg PO q24h; loading: 100-120 mg/kg/day×5日; TDM: 1-3 mg/mL","notes_ja":"犬のてんかん。フェノバルビタール追加/代替。定常状態に3-4ヶ月→ローディング推奨","notes":"Canine epilepsy. PB add-on/alternative. Steady state 3-4 months → loading recommended"}},"side_effects":"PU/PD, sedation, hindlimb ataxia, pancreatitis, rash (rare), bromism","side_effects_ja":"多飲多尿、鎮静、後肢失調、膵炎、発疹（稀）、臭素中毒","contraindications":"CATS (fatal pneumonitis/asthma), renal failure","contraindications_ja":"猫（致死性肺炎/喘息）、腎不全","drug_interactions":[{"drug":"furosemide","severity":"moderate","description_ja":"Br排泄促進→血中濃度低下","description":"Increased Br excretion, lower levels"},{"drug":"chloride_containing_fluids","severity":"moderate","description_ja":"Br排泄促進","description":"Increased Br excretion"}]},
    {"id":"topiramate","name":"Topiramate","name_ja":"トピラマート","category":"behavioral","mechanism":"Multiple mechanisms: blocks sodium channels, enhances GABA, blocks glutamate, inhibits carbonic anhydrase","mechanism_ja":"複数機序：Naチャネル遮断、GABA増強、グルタミン酸遮断、炭酸脱水酵素阻害","species_info":{"dog":{"dose":"2-10 mg/kg PO q8-12h","notes_ja":"難治性てんかんの追加療法","notes":"Refractory epilepsy add-on therapy"},"cat":{"dose":"5-12.5 mg/cat PO q12h","notes_ja":"難治性てんかんの追加","notes":"Refractory epilepsy add-on"}},"side_effects":"Sedation, ataxia, weight loss, metabolic acidosis, renal stones","side_effects_ja":"鎮静、運動失調、体重減少、代謝性アシドーシス、腎結石","contraindications":"Renal stones, metabolic acidosis, hepatic disease","contraindications_ja":"腎結石、代謝性アシドーシス、肝疾患","drug_interactions":[]},
    {"id":"calcium_edta","name":"Calcium EDTA (CaNa2EDTA)","name_ja":"カルシウムEDTA","category":"miscellaneous","mechanism":"Chelating agent; binds divalent and trivalent heavy metals for renal excretion","mechanism_ja":"キレート薬。二価・三価重金属に結合し腎排泄を促進","species_info":{"dog":{"dose":"25 mg/kg SC q6h（希釈）× 5日; 5日休薬後繰返し","notes_ja":"鉛中毒・亜鉛中毒の解毒。SC投与（IV可だが腎毒性↑）","notes":"Lead/zinc toxicity. SC preferred (IV possible but higher nephrotoxicity)"},"cat":{"dose":"25 mg/kg SC q6h × 5日","notes_ja":"鉛中毒","notes":"Lead toxicity"},"bird":{"dose":"20-40 mg/kg IM q12h × 5日","notes_ja":"鳥類の鉛中毒（おもちゃ・釣り重り摂取）","notes":"Avian lead toxicity (toys, fishing sinkers)"},"reptile":{"dose":"20-30 mg/kg IM q12h × 5日","notes_ja":"鉛中毒","notes":"Lead toxicity"}},"side_effects":"Nephrotoxicity, GI upset, pain on injection, zinc depletion","side_effects_ja":"腎毒性、消化器症状、注射時疼痛、亜鉛欠乏","contraindications":"Renal failure, concurrent nephrotoxic drugs","contraindications_ja":"腎不全、腎毒性薬併用","drug_interactions":[]},
    {"id":"deferoxamine","name":"Deferoxamine (Desferal)","name_ja":"デフェロキサミン（デスフェラール）","category":"miscellaneous","mechanism":"Iron chelator; binds free iron and iron in ferritin/hemosiderin for urinary excretion","mechanism_ja":"鉄キレート薬。遊離鉄とフェリチン/ヘモジデリン中の鉄に結合し尿排泄","species_info":{"dog":{"dose":"10-40 mg/kg IM/IV slow q4-8h","notes_ja":"鉄中毒の解毒。vin rosé colored尿で排泄確認","notes":"Iron toxicity. Vin rosé urine confirms excretion"},"cat":{"dose":"10-40 mg/kg IM/IV slow","notes_ja":"鉄中毒","notes":"Iron toxicity"}},"side_effects":"Hypotension (rapid IV), injection site pain, ototoxicity (chronic use)","side_effects_ja":"低血圧（急速IV）、注射部位疼痛、耳毒性（長期使用）","contraindications":"Renal failure (relative)","contraindications_ja":"腎不全（相対的）","drug_interactions":[]},
    {"id":"penicillamine","name":"Penicillamine (Cuprimine)","name_ja":"ペニシラミン（メタルカプターゼ）","category":"miscellaneous","mechanism":"Chelating agent for copper; also used for lead, cystine urolithiasis, and hepatic fibrosis","mechanism_ja":"銅キレート薬。鉛・シスチン尿石症・肝線維症にも使用","species_info":{"dog":{"dose":"10-15 mg/kg PO q12h（空腹時）","notes_ja":"銅蓄積性肝炎（ベドリントンテリア等）・鉛中毒・シスチン尿石症","notes":"Copper-associated hepatitis (Bedlington Terrier), lead toxicity, cystine urolithiasis"},"cat":{"dose":"125 mg/cat PO q12h","notes_ja":"銅蓄積性肝疾患（猫では稀）","notes":"Copper storage hepatopathy (rare in cats)"}},"side_effects":"GI upset, anemia, proteinuria, skin eruptions","side_effects_ja":"消化器症状、貧血、蛋白尿、皮疹","contraindications":"Penicillin allergy (cross-reactivity possible), renal failure","contraindications_ja":"ペニシリンアレルギー（交差反応の可能性）、腎不全","drug_interactions":[{"drug":"zinc","severity":"moderate","description_ja":"ペニシラミン吸収低下（2時間空ける）","description":"Decreased penicillamine absorption (separate by 2h)"}]},
    {"id":"zinc_acetate","name":"Zinc Acetate","name_ja":"酢酸亜鉛","category":"miscellaneous","mechanism":"Induces intestinal metallothionein which binds copper, preventing its absorption","mechanism_ja":"腸管メタロチオネインを誘導し銅に結合、銅吸収を防止","species_info":{"dog":{"dose":"5-10 mg/kg（元素Znとして）PO q12h（食事と2時間離す）","notes_ja":"銅蓄積性肝炎の維持療法（ペニシラミンで銅除去後）。亜鉛欠乏皮膚症にも","notes":"Copper hepatitis maintenance (after penicillamine decopperng). Also for zinc-responsive dermatosis"},"cat":{"dose":"データ限定","notes_ja":"猫での使用は限定的","notes":"Limited use in cats"}},"side_effects":"GI upset, hemolytic anemia (overdose)","side_effects_ja":"消化器症状、溶血性貧血（過量）","contraindications":"Zinc toxicity, concurrent copper deficiency","contraindications_ja":"亜鉛中毒、銅欠乏症","drug_interactions":[]},
    {"id":"pyridostigmine","name":"Pyridostigmine (Mestinon)","name_ja":"ピリドスチグミン（メスチノン）","category":"miscellaneous","mechanism":"Reversible acetylcholinesterase inhibitor; increases acetylcholine at neuromuscular junction","mechanism_ja":"可逆的アセチルコリンエステラーゼ阻害薬。神経筋接合部のアセチルコリンを増加","species_info":{"dog":{"dose":"0.5-3 mg/kg PO q8-12h（個体差大）","notes_ja":"重症筋無力症（MG）。用量は個体反応でtitrate。巨大食道合併に注意","notes":"Myasthenia gravis. Titrate to individual response. Watch for megaesophagus"},"cat":{"dose":"0.25-0.5 mg/kg PO q8-12h","notes_ja":"猫の重症筋無力症（稀）","notes":"Feline myasthenia gravis (rare)"}},"side_effects":"Cholinergic crisis (overdose: salivation, lacrimation, urination, defecation, bradycardia)","side_effects_ja":"コリン作動性クリーゼ（過量：流涎・流涙・排尿・排便・徐脈）","contraindications":"GI/urinary obstruction, concurrent depolarizing NMB","contraindications_ja":"消化管/泌尿器閉塞、脱分極性NMB併用","drug_interactions":[{"drug":"atropine","severity":"moderate","description_ja":"ピリドスチグミンの効果を部分的に拮抗","description":"Partially antagonizes pyridostigmine effect"}]},
    {"id":"propantheline","name":"Propantheline","name_ja":"プロパンテリン","category":"miscellaneous","mechanism":"Anticholinergic/antispasmodic; reduces GI and urinary smooth muscle spasm","mechanism_ja":"抗コリン/鎮痙薬。消化管・泌尿器平滑筋の痙攣を抑制","species_info":{"dog":{"dose":"0.25-0.5 mg/kg PO q8-12h","notes_ja":"排尿筋過活動（尿失禁の一因）・消化管痙攣","notes":"Detrusor overactivity (urinary incontinence), GI spasm"},"cat":{"dose":"7.5 mg/cat PO q72h","notes_ja":"猫の機能性大腸疾患","notes":"Feline functional large bowel disease"}},"side_effects":"Dry mouth, constipation, urinary retention, tachycardia","side_effects_ja":"口渇、便秘、尿閉、頻脈","contraindications":"GI obstruction, glaucoma, urinary obstruction","contraindications_ja":"消化管閉塞、緑内障、尿路閉塞","drug_interactions":[]},
    {"id":"deslorelin_implant","name":"Deslorelin Implant (Suprelorin)","name_ja":"デスロレリンインプラント（スプレロリン）","category":"reproductive","mechanism":"GnRH agonist; initial stimulation then downregulation of LH/FSH (chemical castration)","mechanism_ja":"GnRHアゴニスト。初期刺激後にLH/FSHをダウンレギュレーション（化学的去勢）","species_info":{"dog":{"dose":"4.7 mg インプラント SC（効果6-12ヶ月）; 9.4 mg（12-24ヶ月）","notes_ja":"化学的去勢。不妊の可逆的代替。初期2-4週はフレアアップ（テストステロン一時上昇）","notes":"Chemical castration. Reversible fertility alternative. Initial 2-4 week flare-up (transient testosterone rise)"},"cat":{"dose":"4.7 mg インプラント SC","notes_ja":"猫の化学的去勢","notes":"Feline chemical castration"},"ferret":{"dose":"4.7 mg インプラント SC","notes_ja":"フェレットの副腎疾患治療（GnRH↓でステロイド産生↓）。去勢の代替","notes":"Ferret adrenal disease (reduced GnRH → reduced steroid production). Castration alternative"}},"side_effects":"Initial flare-up (2-4 weeks), injection site reaction, variable duration","side_effects_ja":"初期フレアアップ（2-4週間）、注射部位反応、効果持続期間のばらつき","contraindications":"Existing testicular/adrenal neoplasia where flare-up is dangerous","contraindications_ja":"フレアアップが危険な精巣/副腎腫瘍","drug_interactions":[]},
    {"id":"testosterone_cypionate","name":"Testosterone Cypionate","name_ja":"テストステロンシピオネート","category":"reproductive","mechanism":"Androgen replacement; restores testosterone-dependent functions","mechanism_ja":"アンドロゲン補充。テストステロン依存性機能を回復","species_info":{"dog":{"dose":"1-2 mg/kg IM q4-8週","notes_ja":"去勢後尿失禁（雄犬）。ペニス萎縮・筋肉量低下の改善","notes":"Post-castration urinary incontinence (male dogs). Penile atrophy, muscle mass restoration"}},"side_effects":"Aggression, prostatic hyperplasia, hepatotoxicity","side_effects_ja":"攻撃性増加、前立腺肥大、肝毒性","contraindications":"Prostatic disease, hepatic disease, intact males","contraindications_ja":"前立腺疾患、肝疾患、未去勢雄","drug_interactions":[]},
    {"id":"diethylstilbestrol","name":"Diethylstilbestrol (DES)","name_ja":"ジエチルスチルベストロール（DES）","category":"reproductive","mechanism":"Synthetic estrogen; increases urethral sphincter tone via estrogen receptor activation","mechanism_ja":"合成エストロゲン。エストロゲン受容体活性化で尿道括約筋緊張を増加","species_info":{"dog":{"dose":"0.1-1 mg/dog PO q24h × 3-5日, 以後0.1-1 mg 週1回","notes_ja":"避妊手術後尿失禁（雌犬）。骨髄抑制リスクのためモニタリング必須","notes":"Post-spay urinary incontinence (female dogs). Monitor for bone marrow suppression"}},"side_effects":"Bone marrow suppression (dose-dependent), estrus signs, alopecia","side_effects_ja":"骨髄抑制（用量依存性）、発情徴候、脱毛","contraindications":"Bone marrow disease, concurrent myelosuppressive drugs","contraindications_ja":"骨髄疾患、骨髄抑制薬併用","drug_interactions":[]},
    {"id":"phenylpropanolamine_ui","name":"Phenylpropanolamine (Urinary Incontinence)","name_ja":"フェニルプロパノールアミン（尿失禁）","category":"miscellaneous","mechanism":"α1-adrenergic agonist; increases urethral sphincter tone","mechanism_ja":"α1アドレナリン作動薬。尿道括約筋緊張を増加","species_info":{"dog":{"dose":"1-2 mg/kg PO q8-12h","notes_ja":"避妊手術後尿失禁の第一選択。75-90%で有効","notes":"First-line post-spay incontinence. 75-90% efficacy"},"cat":{"dose":"1-1.5 mg/kg PO q12h","notes_ja":"猫の尿失禁（稀な適応）","notes":"Feline urinary incontinence (rare indication)"}},"side_effects":"Hypertension, tachycardia, restlessness, inappetence","side_effects_ja":"高血圧、頻脈、不穏、食欲不振","contraindications":"Hypertension, cardiac disease, glaucoma","contraindications_ja":"高血圧、心疾患、緑内障","drug_interactions":[{"drug":"maois","severity":"major","description_ja":"高血圧クリーゼ","description":"Hypertensive crisis"}]},
    {"id":"cisplatin_injectable","name":"Cisplatin Injectable","name_ja":"シスプラチン注射","category":"antineoplastic","mechanism":"Platinum compound; cross-links DNA causing cell death. Dose-limiting nephrotoxicity","mechanism_ja":"白金製剤。DNAを架橋し細胞死を誘導。用量制限因子は腎毒性","species_info":{"dog":{"dose":"60-70 mg/m² IV q21日（生理食塩水利尿と併用必須）","notes_ja":"骨肉腫（術後補助）・膀胱TCC・鼻腔腫瘍。4時間の生理食塩水利尿プロトコル必須","notes":"Osteosarcoma (adjuvant), bladder TCC, nasal tumor. 4-hour saline diuresis protocol REQUIRED"}},"side_effects":"Nephrotoxicity (dose-limiting), severe nausea/vomiting, myelosuppression, ototoxicity","side_effects_ja":"腎毒性（用量制限）、重度悪心/嘔吐、骨髄抑制、耳毒性","contraindications":"CATS (fatal pulmonary edema), renal disease, dehydration","contraindications_ja":"猫（致死性肺水腫）、腎疾患、脱水","drug_interactions":[{"drug":"aminoglycosides","severity":"major","description_ja":"腎毒性の相加","description":"Additive nephrotoxicity"},{"drug":"furosemide","severity":"moderate","description_ja":"腎毒性増加の可能性","description":"Possible increased nephrotoxicity"}]},
    {"id":"lomustine_oral","name":"Lomustine (CCNU) Oral","name_ja":"ロムスチン（CCNU）経口","category":"antineoplastic","mechanism":"Nitrosourea alkylating agent; crosses blood-brain barrier. Lipophilic","mechanism_ja":"ニトロソウレアアルキル化薬。血液脳関門を通過。脂溶性","species_info":{"dog":{"dose":"60-90 mg/m² PO q3週; CBC必須（投与前好中球>3000）","notes_ja":"肥満細胞腫・リンパ腫・脳腫瘍・組織球性肉腫。累積肝毒性に注意","notes":"Mast cell tumor, lymphoma, brain tumor, histiocytic sarcoma. Cumulative hepatotoxicity"},"cat":{"dose":"50-60 mg/m² PO q3-6週","notes_ja":"猫のリンパ腫・肥満細胞腫","notes":"Feline lymphoma, mast cell tumor"}},"side_effects":"Delayed myelosuppression (nadir 7 days neutrophils, 21 days platelets), cumulative hepatotoxicity, GI upset","side_effects_ja":"遅発性骨髄抑制（好中球最低値7日、血小板21日）、累積肝毒性、消化器症状","contraindications":"Hepatic disease, bone marrow failure","contraindications_ja":"肝疾患、骨髄不全","drug_interactions":[]},
    {"id":"prednisolone_lymphoma","name":"Prednisolone (Lymphoma Protocol)","name_ja":"プレドニゾロン（リンパ腫プロトコル）","category":"antineoplastic","mechanism":"Direct lymphocytotoxic effect; induces apoptosis in lymphoid cells","mechanism_ja":"直接的リンパ球毒性。リンパ系細胞のアポトーシスを誘導","species_info":{"dog":{"dose":"CHOP内: 2 mg/kg PO q24h × 7日→1.5→1→0.5 mg/kg 漸減","notes_ja":"リンパ腫CHOP/COP protocolの必須構成薬。単剤でもCR率50%だが短期","notes":"Essential CHOP/COP component. Single-agent CR rate 50% but short-lived"},"cat":{"dose":"COP内: 2 mg/kg PO q24h × 7日→漸減; 小細胞: 10 mg/cat PO q12h","notes_ja":"猫のリンパ腫。小細胞型はクロラムブシル＋プレドニゾロンが標準","notes":"Feline lymphoma. Small cell: chlorambucil + prednisolone is standard"}},"side_effects":"PU/PD, polyphagia, GI ulceration, diabetes (cats), iatrogenic Cushing's","side_effects_ja":"多飲多尿、多食、消化管潰瘍、糖尿病（猫）、医原性クッシング","contraindications":"Prior to biopsy (can obscure diagnosis)","contraindications_ja":"生検前（診断を不明瞭にする可能性）","drug_interactions":[]},
    {"id":"hydroxyurea","name":"Hydroxyurea","name_ja":"ヒドロキシウレア","category":"antineoplastic","mechanism":"Inhibits ribonucleotide reductase; blocks DNA synthesis (S-phase specific)","mechanism_ja":"リボヌクレオチド還元酵素を阻害。DNA合成を遮断（S期特異的）","species_info":{"dog":{"dose":"50 mg/kg PO 2-3回/週; 用量調整はCBCで","notes_ja":"真性多血症・慢性骨髄性白血病・肥満細胞腫（経口維持）","notes":"Polycythemia vera, CML, mast cell tumor (oral maintenance)"},"cat":{"dose":"25-30 mg/kg PO q48-72h","notes_ja":"猫の骨髄増殖性疾患","notes":"Feline myeloproliferative disease"}},"side_effects":"Myelosuppression, GI upset, nail sloughing (cats)","side_effects_ja":"骨髄抑制、消化器症状、爪脱落（猫）","contraindications":"Severe myelosuppression","contraindications_ja":"重度骨髄抑制","drug_interactions":[]},
    {"id":"mirtazapine_transdermal","name":"Mirtazapine Transdermal (Mirataz)","name_ja":"ミルタザピン経皮（ミラタズ）","category":"gastrointestinal","mechanism":"NaSSA antidepressant; appetite stimulation via serotonin and histamine receptor modulation","mechanism_ja":"NaSSA抗うつ薬。セロトニン・ヒスタミン受容体調節で食欲刺激","species_info":{"cat":{"dose":"1.5インチリボン 耳介内側 q48h","notes_ja":"猫の体重減少・食欲不振に唯一認可された経皮剤。CKD・がんで使用","notes":"Only approved transdermal for feline weight loss/inappetence. Used in CKD, cancer"}},"side_effects":"Application site reactions, vocalization, restlessness","side_effects_ja":"塗布部位反応、発声、不穏","contraindications":"Concurrent MAOIs, severe hepatic disease","contraindications_ja":"MAOI併用、重度肝疾患","drug_interactions":[{"drug":"fluoxetine","severity":"major","description_ja":"セロトニン症候群リスク","description":"Serotonin syndrome risk"}]},
    {"id":"rutin","name":"Rutin (Bioflavonoid)","name_ja":"ルチン（バイオフラボノイド）","category":"miscellaneous","mechanism":"Bioflavonoid; strengthens capillary endothelium and promotes lymphatic drainage","mechanism_ja":"バイオフラボノイド。毛細血管内皮を強化しリンパ排出を促進","species_info":{"guinea_pig":{"dose":"50-200 mg/kg PO q12h","notes_ja":"モルモットの卵巣嚢胞に伴う腹水・リンパ浮腫の補助療法","notes":"Guinea pig ovarian cyst-associated ascites, lymphedema adjunct"},"dog":{"dose":"50 mg/kg PO q12h","notes_ja":"乳び胸の補助療法。脂肪制限食と併用","notes":"Chylothorax adjunct. Combine with low-fat diet"},"cat":{"dose":"50-200 mg/kg PO q12h","notes_ja":"猫の乳び胸補助療法","notes":"Feline chylothorax adjunct"}},"side_effects":"None significant","side_effects_ja":"特になし","contraindications":"None known","contraindications_ja":"なし","drug_interactions":[]},
    {"id":"sardine_oil","name":"Sardine/Anchovy Oil (Omega-3 Source)","name_ja":"イワシ/アンチョビオイル（オメガ3源）","category":"miscellaneous","mechanism":"Marine-derived EPA/DHA; anti-inflammatory via competitive arachidonic acid pathway inhibition","mechanism_ja":"海洋由来EPA/DHA。アラキドン酸経路の競合的阻害で抗炎症","species_info":{"dog":{"dose":"1-2 mL/10kg PO q24h（食事に混合）","notes_ja":"OA・アトピー・CKD・心疾患の補助。フィッシュオイルの具体的な投与源","notes":"OA, atopy, CKD, cardiac disease adjunct. Specific fish oil source"},"cat":{"dose":"0.5-1 mL/cat PO q24h","notes_ja":"CKD・OA補助。IRIS推奨のオメガ3源","notes":"CKD, OA adjunct. IRIS-recommended omega-3 source"}},"side_effects":"Fishy breath, loose stools at high dose","side_effects_ja":"魚臭い口臭、高用量で軟便","contraindications":"Pancreatitis (high fat)","contraindications_ja":"膵炎（高脂肪）","drug_interactions":[]},
    {"id":"vitamin_c_guinea_pig","name":"Vitamin C (Ascorbic Acid) for Guinea Pigs","name_ja":"ビタミンC（アスコルビン酸）モルモット用","category":"miscellaneous","mechanism":"Essential vitamin; guinea pigs (like humans) cannot synthesize ascorbic acid (lack L-gulonolactone oxidase)","mechanism_ja":"必須ビタミン。モルモットはヒト同様アスコルビン酸を合成できない（L-グロノラクトンオキシダーゼ欠損）","species_info":{"guinea_pig":{"dose":"50-100 mg/kg PO q24h（予防）; 壊血病治療: 100-200 mg/kg q24h","notes_ja":"モルモット必須。壊血病予防に毎日投与。新鮮な野菜からも摂取可能だが不十分なことが多い","notes":"ESSENTIAL for guinea pigs. Daily supplementation prevents scurvy. Fresh vegetables may be insufficient"}},"side_effects":"None at recommended doses; diarrhea at very high doses","side_effects_ja":"推奨用量では特になし。極端な高用量で下痢","contraindications":"None","contraindications_ja":"なし","drug_interactions":[]},
    {"id":"calcium_supplement_reptile","name":"Calcium Carbonate Powder (Reptile)","name_ja":"炭酸カルシウム粉末（爬虫類用）","category":"miscellaneous","mechanism":"Oral calcium supplementation for bone mineralization in reptiles","mechanism_ja":"爬虫類の骨石灰化のための経口カルシウム補給","species_info":{"reptile":{"dose":"餌にダスティング（毎回の給餌時）","notes_ja":"爬虫類のMBD予防に必須。UVBライト（+ビタミンD3）と併用が必要","notes":"ESSENTIAL for reptilian MBD prevention. Must combine with UVB lighting (+vitamin D3)"},"tortoise":{"dose":"餌にダスティング q1-2日","notes_ja":"リクガメのMBD予防","notes":"Tortoise MBD prevention"},"lizard":{"dose":"餌にダスティング（毎回）","notes_ja":"トカゲのMBD予防","notes":"Lizard MBD prevention"},"amphibian":{"dose":"餌の昆虫にダスティング","notes_ja":"両生類のMBD予防","notes":"Amphibian MBD prevention"},"bird":{"dose":"カトルボーン/ミネラルブロック; 卵塞時100-200 mg/kg PO","notes_ja":"産卵期のCa補給・卵塞予防","notes":"Laying period Ca supplementation, egg binding prevention"}},"side_effects":"Constipation (excessive), hypercalcemia (with excessive D3)","side_effects_ja":"便秘（過剰時）、高カルシウム血症（D3過剰併用時）","contraindications":"Hypercalcemia","contraindications_ja":"高カルシウム血症","drug_interactions":[]},
    {"id":"uvb_therapy","name":"UVB Phototherapy (Reptile Husbandry)","name_ja":"UVB光線療法（爬虫類飼育管理）","category":"miscellaneous","mechanism":"UVB radiation (290-320nm) enables cutaneous synthesis of vitamin D3 from 7-dehydrocholesterol","mechanism_ja":"UVB放射線（290-320nm）が皮膚で7-デヒドロコレステロールからビタミンD3を合成","species_info":{"reptile":{"dose":"5.0-12.0% UVB（種による）; 10-12時間/日; 6ヶ月毎にバルブ交換","notes_ja":"爬虫類のMBD予防の根幹。カルシウム補給と併用必須。種により必要UVB量が異なる","notes":"Foundation of reptilian MBD prevention. Must combine with calcium. UVB needs vary by species"},"tortoise":{"dose":"10.0-12.0% UVB; 10-12時間/日","notes_ja":"リクガメは高UVB要求","notes":"Tortoises require high UVB"},"lizard":{"dose":"5.0-12.0% UVB（種による）","notes_ja":"昼行性トカゲに必須","notes":"Essential for diurnal lizards"},"amphibian":{"dose":"2.0-5.0% UVB; 一部種は不要","notes_ja":"一部の両生類に有益","notes":"Beneficial for some amphibians"}},"side_effects":"Photokeratoconjunctivitis (improper lamp placement), thermal burns","side_effects_ja":"光角結膜炎（不適切なランプ配置）、熱傷","contraindications":"Nocturnal species that avoid UV","contraindications_ja":"UVを避ける夜行性種","drug_interactions":[]}
